import React, { useState } from 'react';
import '../styles/theme.css';

export default function NewPurchase() {
  const [formData, setFormData] = useState({
    date: new Date().toISOString().split('T')[0],
    farmerName: '',
    village: '',
    grainType: 'Wheat (Gehun)',
    bags: '',
    grossWeight: '',
    tareWeight: '',
    bardanaWeight: '',
    moisture: '',
    rate: '',
    hamali: '5.00', // per quintal handling charges
    commission: '2.5' // % Arht
  });

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  // Advanced Mandi Calculations
  const gross = Number(formData.grossWeight) || 0;
  const tare = Number(formData.tareWeight) || 0;
  const bardana = Number(formData.bardanaWeight) || 0;
  
  // Net Weight = Gross - Tare - Bardana deduction
  const netWeight = Math.max(0, (gross - tare - bardana)).toFixed(2);
  
  // Total Grain Amount = Net Weight (in Quintals) * Rate
  const grainAmount = (Number(netWeight) * (Number(formData.rate) || 0)).toFixed(2);
  
  // Deductions
  const hamaliTotal = (Number(netWeight) * (Number(formData.hamali) || 0)).toFixed(2);
  const commissionTotal = (Number(grainAmount) * (Number(formData.commission) / 100)).toFixed(2);
  
  // Final Payable Amount to Farmer
  const netPayable = (Number(grainAmount) - Number(hamaliTotal) - Number(commissionTotal)).toFixed(2);

  return (
    <div style={{ padding: '24px', maxWidth: '1000px', margin: '0 auto', fontFamily: 'Segoe UI, sans-serif' }}>
      <div style={{ background: '#1B4D3E', color: '#fff', padding: '20px', borderRadius: '8px 8px 0 0', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
        <h2 style={{ margin: 0, fontSize: '20px' }}>📦 Advanced Mandi Purchase Entry (RK Sons)</h2>
        <span style={{ background: '#2E7D32', padding: '5px 12px', borderRadius: '4px', fontSize: '14px' }}>Draft Invoice</span>
      </div>

      <div style={{ background: '#ffffff', padding: '30px', borderRadius: '0 0 8px 8px', boxShadow: '0 4px 15px rgba(0,0,0,0.05)' }}>
        <form style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '20px' }}>
          
          {/* Date */}
          <div>
            <label style={labelStyle}>Purchase Date</label>
            <input type="date" name="date" value={formData.date} onChange={handleChange} style={inputStyle} />
          </div>

          {/* Farmer Name */}
          <div>
            <label style={labelStyle}>Farmer / Seller Name</label>
            <input type="text" name="farmerName" placeholder="e.g. Ramesh Singh" value={formData.farmerName} onChange={handleChange} style={inputStyle} />
          </div>

          {/* Village */}
          <div>
            <label style={labelStyle}>Village / Mandi Source</label>
            <input type="text" name="village" placeholder="e.g. Pipariya" value={formData.village} onChange={handleChange} style={inputStyle} />
          </div>

          {/* Grain Type */}
          <div>
            <label style={labelStyle}>Grain Commodity</label>
            <select name="grainType" value={formData.grainType} onChange={handleChange} style={inputStyle}>
              <option>Wheat (Gehun)</option>
              <option>Paddy (Dhaan)</option>
              <option>Soyabean</option>
              <option>Mustard (Sarso)</option>
            </select>
          </div>

          {/* Bags */}
          <div>
            <label style={labelStyle}>Total Bags (Gunny)</label>
            <input type="number" name="bags" placeholder="100" value={formData.bags} onChange={handleChange} style={inputStyle} />
          </div>

          {/* Gross Weight */}
          <div>
            <label style={labelStyle}>Gross Weight (Qtl)</label>
            <input type="number" name="grossWeight" placeholder="52.50" value={formData.grossWeight} onChange={handleChange} style={inputStyle} />
          </div>

          {/* Tare Weight */}
          <div>
            <label style={labelStyle}>Tare / Vehicle Weight (Qtl)</label>
            <input type="number" name="tareWeight" placeholder="12.00" value={formData.tareWeight} onChange={handleChange} style={inputStyle} />
          </div>

          {/* Bardana Deduction */}
          <div>
            <label style={labelStyle}>Bardana Deduction (Qtl)</label>
            <input type="number" name="bardanaWeight" placeholder="0.50" value={formData.bardanaWeight} onChange={handleChange} style={inputStyle} />
          </div>

          {/* Rate */}
          <div>
            <label style={labelStyle}>Rate per Quintal (₹)</label>
            <input type="number" name="rate" placeholder="2650" value={formData.rate} onChange={handleChange} style={inputStyle} />
          </div>

        </form>

        {/* Live Calculation Summary Box */}
        <div style={{ marginTop: '30px', background: '#F4F7F6', padding: '20px', borderRadius: '8px', borderLeft: '5px solid #1B4D3E' }}>
          <h3 style={{ margin: '0 0 15px 0', color: '#1B4D3E', fontSize: '16px' }}>⚖️ Live Mandi Computation</h3>
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: '15px', textAlign: 'center' }}>
            <div style={calcCard}>
              <span style={calcLabel}>Net Weight</span>
              <span style={calcValue}>{netWeight} Qtl</span>
            </div>
            <div style={calcCard}>
              <span style={calcLabel}>Grain Amount</span>
              <span style={calcValue}>₹ {grainAmount}</span>
            </div>
            <div style={calcCard}>
              <span style={calcLabel}>Deductions (Hamali/Comm)</span>
              <span style={{...calcValue, color: '#C0392B'}}>- ₹ {(Number(hamaliTotal) + Number(commissionTotal)).toFixed(2)}</span>
            </div>
            <div style={{...calcCard, background: '#1B4D3E', color: '#fff'}}>
              <span style={{...calcLabel, color: '#A3E4D7'}}>Net Payable to Farmer</span>
              <span style={{...calcValue, color: '#fff', fontSize: '18px'}}>₹ {netPayable}</span>
            </div>
          </div>
        </div>

        {/* Action Buttons */}
        <div style={{ marginTop: '25px', display: 'flex', gap: '15px', justifyContent: 'flex-end' }}>
          <button style={{ background: '#7F8C8D', color: '#fff', border: 'none', padding: '12px 25px', borderRadius: '6px', fontWeight: 'bold', cursor: 'pointer' }}>Cancel</button>
          <button style={{ background: '#27AE60', color: '#fff', border: 'none', padding: '12px 25px', borderRadius: '6px', fontWeight: 'bold', cursor: 'pointer' }}>Save & Print Bill</button>
          <button style={{ background: '#1B4D3E', color: '#fff', border: 'none', padding: '12px 25px', borderRadius: '6px', fontWeight: 'bold', cursor: 'pointer' }}>Save & Share via WhatsApp</button>
        </div>

      </div>
    </div>
  );
}

